mcp_tools.body:
[
 {
  "description": "Install all skills from a bundle (bulk) or one skill by slug. bdl_token callers may omit bundle_id — it defaults to the token's scoped bundle. user/master callers must pass bundle_id.",
  "inputSchema": {
   "properties": {
    "bundle_id": {
     "description": "Bundle UUID. Optional for bdl_token (defaults to token's bundle_scope); required otherwise.",
     "type": "string"
    },
    "slug": {
     "description": "Optional single-skill filter. Omit to bulk-install every active skill in the bundle.",
     "type": "string"
    }
   },
   "type": "object"
  },
  "name": "bundle_install"
 },
 {
  "description": "List the caller's bundle and its skill provenance rows.",
  "inputSchema": {
   "properties": {
    "bundle_id": {
     "type": "string"
    }
   },
   "type": "object"
  },
  "name": "bundle_list"
 },
 {
  "description": "Deploy a tailored fork's latest version into one of your bundles. Promotes the fork into a private catalog skill linked to the bundle and mints an installable version, so it installs byte-identically to any catalog skill via loopskill_bundle_install. Step 3 of the tailor loop. Pro tier or above; you must own the bundle.",
  "inputSchema": {
   "properties": {
    "fork_id": {
     "description": "UUID of the fork to deploy (must have an uploaded version).",
     "type": "string"
    },
    "slug": {
     "description": "Optional slug override for the promoted skill (defaults to the fork slug). Must match ^[a-z0-9][a-z0-9_-]{0,63}$.",
     "type": "string"
    },
    "target_cookbook_id": {
     "description": "UUID of the bundle to attach the promoted skill to (you must own it).",
     "type": "string"
    }
   },
   "required": [
    "fork_id",
    "target_cookbook_id"
   ],
   "type": "object"
  },
  "name": "loopskill_bundle_attach"
 },
 {
  "description": "Transfer OR fork a bundle to a new owner preserving tailored skills. Only the current owner or master may act. Provide new_owner_user_id OR new_owner_email. mode='transfer': ownership swaps in-place. mode='fork': new bundle with parent lineage + custom-added skills.",
  "inputSchema": {
   "properties": {
    "cookbook_id": {
     "description": "UUID of the bundle to hand off.",
     "type": "string"
    },
    "mode": {
     "default": "transfer",
     "enum": [
      "transfer",
      "fork"
     ],
     "type": "string"
    },
    "new_owner_email": {
     "description": "Email of the new owner (or use new_owner_user_id).",
     "type": "string"
    },
    "new_owner_user_id": {
     "description": "UUID of the new owner (or use new_owner_email).",
     "type": "string"
    }
   },
   "required": [
    "cookbook_id"
   ],
   "type": "object"
  },
  "name": "loopskill_bundle_handoff"
 },
 {
  "description": "Install all skills from a bundle (bulk) or one skill by slug. cbt_token callers may omit cookbook_id — it defaults to the token's scoped bundle. user/master callers must pass cookbook_id. The single-skill payload mirrors loopskill_install; the bulk payload mirrors POST /api/cookbooks/{id}/install.",
  "inputSchema": {
   "properties": {
    "cookbook_id": {
     "description": "Bundle UUID. Optional for cbt_token (defaults to token's bundle_scope); required otherwise.",
     "type": "string"
    },
    "slug": {
     "description": "Optional single-skill filter. Omit to bulk-install every active skill in the bundle.",
     "type": "string"
    }
   },
   "type": "object"
  },
  "name": "loopskill_bundle_install"
 },
 {
  "description": "Compose a NEW bundle (owned by you) from N links in one call. The 'streaming' compose verb — each link can be a public bundle (bundle://<slug> → all its skills), an internal catalogue skill (skill://<slug>), or an external federated skill (<source>:<slug>, e.g. clawhub:web-scraper). The de-duplicated union becomes a new private bundle you own; publish it to get a shareable bundle:// link. Requires an authenticated user; honors your tier's bundle cap.",
  "inputSchema": {
   "properties": {
    "links": {
     "description": "1–25 links to compose from (bundle / skill / external).",
     "items": {
      "type": "string"
     },
     "type": "array"
    },
    "name": {
     "description": "Optional name for the new bundle (default auto-generated).",
     "type": "string"
    }
   },
   "required": [
    "links"
   ],
   "type": "object"
  },
  "name": "loopskill_compose_bundle_from_links"
 },
 {
  "description": "Configure per-bundle feedback routing to the user's own GitHub repo. Pro/Pro+ only. Pass repo='owner/name', mode='pat', and a fine-grained GitHub PAT with issues:write to route feedback issues to your repo. Pass repo=None to clear and revert to default (wisechef-ai/loopskill-api).",
  "inputSchema": {
   "properties": {
    "cookbook_id": {
     "description": "UUID of the bundle to configure. Defaults to caller's personal bundle.",
     "type": "string"
    },
    "mode": {
     "description": "'pat' — store a fine-grained GitHub PAT (issues:write). 'github_app' — future App token (not yet live).",
     "enum": [
      "pat",
      "github_app"
     ],
     "type": "string"
    },
    "pat": {
     "description": "Fine-grained GitHub PAT with issues:write on the target repo. Required when mode='pat'. Never logged.",
     "type": "string"
    },
    "repo": {
     "description": "GitHub 'owner/name' repo to route feedback issues to. Pass null/omit to clear custom routing.",
     "type": "string"
    }
   },
   "type": "object"
  },
  "name": "loopskill_configure_feedback"
 },
 {
  "description": "Publish a Connector (MCP-server config fragment) — create the connector if it doesn't exist, then mint a version with the config_template. The template uses ${VAR} env refs only; literal secrets are rejected at publish time. One call.",
  "inputSchema": {
   "properties": {
    "changelog": {
     "type": "string"
    },
    "config_template": {
     "type": "object"
    },
    "connector_type": {
     "enum": [
      "stdio",
      "http",
      "sse"
     ],
     "type": "string"
    },
    "description": {
     "type": "string"
    },
    "required_env": {
     "items": {
      "type": "string"
     },
     "type": "array"
    },
    "residency_tag": {
     "type": "string"
    },
    "semver": {
     "type": "string"
    },
    "slug": {
     "type": "string"
    },
    "title": {
     "type": "string"
    }
   },
   "required": [
    "slug",
    "title",
    "connector_type",
    "semver",
    "config_template"
   ],
   "type": "object"
  },
  "name": "loopskill_connector_publish"
 },
 {
  "description": "Audit a local skill install directory for missing files and hardcoded paths.",
  "inputSchema": {
   "properties": {
    "install_dir": {
     "type": "string"
    }
   },
   "required": [
    "install_dir"
   ],
   "type": "object"
  },
  "name": "loopskill_doctor"
 },
 {
  "description": "Send feedback about LoopSkill (app.loopskill.io). Use when the user says 'write feedback that...', 'give feedback...', 'report that...', or expresses frustration with the platform UX, search, billing, or docs. Auto-creates a labelled GitHub issue. Rate limited per 24h.",
  "inputSchema": {
   "properties": {
    "agent_id": {
     "type": "string"
    },
    "category": {
     "enum": [
      "ux",
      "search",
      "billing",
      "docs",
      "install",
      "other"
     ],
     "type": "string"
    },
    "confirmation": {
     "type": "string"
    },
    "context": {
     "type": "object"
    },
    "force": {
     "default": false,
     "type": "boolean"
    },
    "message": {
     "type": "string"
    },
    "provenance_id": {
     "description": "Install-provenance token; routes to the right creator repo (Ph E).",
     "type": "string"
    }
   },
   "required": [
    "category",
    "message"
   ],
   "type": "object"
  },
  "name": "loopskill_feedback"
 },
 {
  "description": "Create a named fleet of agents. Returns a one-time fleet API key (rec_fleet_*) for x-fleet-key authentication. The key is shown ONCE.",
  "inputSchema": {
   "properties": {
    "name": {
     "type": "string"
    }
   },
   "required": [
    "name"
   ],
   "type": "object"
  },
  "name": "loopskill_fleet_create"
 },
 {
  "description": "List all fleets owned by the caller with their bundle subscriptions.",
  "inputSchema": {
   "properties": {},
   "type": "object"
  },
  "name": "loopskill_fleet_list"
 },
 {
  "description": "Subscribe a bundle to a fleet on a given channel (stable, canary, frozen). Idempotent.",
  "inputSchema": {
   "properties": {
    "channel": {
     "default": "stable",
     "enum": [
      "stable",
      "canary",
      "frozen"
     ],
     "type": "string"
    },
    "cookbook_id": {
     "type": "string"
    },
    "fleet_id": {
     "type": "string"
    }
   },
   "required": [
    "fleet_id",
    "cookbook_id"
   ],
   "type": "object"
  },
  "name": "loopskill_fleet_subscribe"
 },
 {
  "description": "Synchronise all bundles subscribed to the fleet. Aggregates per-bundle sync results. Pass dry_run=true to preview.",
  "inputSchema": {
   "properties": {
    "dry_run": {
     "default": false,
     "description": "If true, preview changes without applying.",
     "type": "boolean"
    },
    "fleet_id": {
     "type": "string"
    }
   },
   "required": [
    "fleet_id"
   ],
   "type": "object"
  },
  "name": "loopskill_fleet_sync"
 },
 {
  "description": "List all forks owned by the authenticated user. Returns fork_id, name, slug, source_slug for each.",
  "inputSchema": {
   "properties": {},
   "type": "object"
  },
  "name": "loopskill_fork_list"
 },
 {
  "description": "Pull a composite loop's full composition by slug.",
  "inputSchema": {
   "properties": {
    "slug": {
     "type": "string"
    }
   },
   "required": [
    "slug"
   ],
   "type": "object"
  },
  "name": "loopskill_get_composite_loop"
 },
 {
  "description": "Pull a single verifier's full safety-bounded execution contract (success_condition, verification_script, stopping_criteria, max_turns, tool_allowlist, system_prompt) by slug.",
  "inputSchema": {
   "properties": {
    "slug": {
     "type": "string"
    }
   },
   "required": [
    "slug"
   ],
   "type": "object"
  },
  "name": "loopskill_get_loop"
 },
 {
  "description": "Pull a personality's system prompt + config by slug.",
  "inputSchema": {
   "properties": {
    "slug": {
     "type": "string"
    }
   },
   "required": [
    "slug"
   ],
   "type": "object"
  },
  "name": "loopskill_get_personality"
 },
 {
  "description": "Pull a single verifier's full safety-bounded execution contract (success_condition, verification_script, stopping_criteria, max_turns, tool_allowlist, system_prompt) by slug.",
  "inputSchema": {
   "properties": {
    "slug": {
     "type": "string"
    }
   },
   "required": [
    "slug"
   ],
   "type": "object"
  },
  "name": "loopskill_get_verifier"
 },
 {
  "description": "Return a signed tarball URL + manifest for a skill slug.",
  "inputSchema": {
   "properties": {
    "slug": {
     "type": "string"
    }
   },
   "required": [
    "slug"
   ],
   "type": "object"
  },
  "name": "loopskill_install"
 },
 {
  "description": "Install every skill in a PUBLIC bundle from one link. The 'streaming' install verb — pass a bundle link (bundle://<slug>, bundle:<slug>, or a bare slug) and get every skill's install line in one call. Anonymous-reachable: a public bundle's skills stream to anyone, like a public playlist's tracks. This is the one-line clone the public bundle page surfaces.",
  "inputSchema": {
   "properties": {
    "link": {
     "description": "Public bundle link: bundle://<slug>, bundle:<slug>, or a bare slug. A trailing ?ref=<creator> is tolerated and stripped.",
     "type": "string"
    }
   },
   "required": [
    "link"
   ],
   "type": "object"
  },
  "name": "loopskill_install_from_bundle"
 },
 {
  "description": "Like or unlike a skill, personality, or loop in the caller's Liked bundle.",
  "inputSchema": {
   "properties": {
    "action": {
     "enum": [
      "like",
      "unlike"
     ],
     "type": "string"
    },
    "id": {
     "description": "Artifact UUID.",
     "type": "string"
    },
    "type": {
     "enum": [
      "skill",
      "personality",
      "loop"
     ],
     "type": "string"
    }
   },
   "required": [
    "action",
    "type",
    "id"
   ],
   "type": "object"
  },
  "name": "loopskill_like"
 },
 {
  "description": "List the caller's bundle and its skill provenance rows.",
  "inputSchema": {
   "properties": {
    "cookbook_id": {
     "type": "string"
    }
   },
   "type": "object"
  },
  "name": "loopskill_list_bundle"
 },
 {
  "description": "Pick the single best skill from a PUBLIC bundle for a stated need. The 'streaming' choose verb — pass a bundle link and an optional 'need' description; returns the best-matching skill (keyword relevance, then real 7d/total installs) plus its install line, and the full ranked list. With no 'need', ranks the whole bundle by installs.",
  "inputSchema": {
   "properties": {
    "link": {
     "description": "Public bundle link (bundle://<slug> / bundle:<slug> / bare slug).",
     "type": "string"
    },
    "need": {
     "description": "Optional natural-language description of what the agent needs.",
     "type": "string"
    }
   },
   "required": [
    "link"
   ],
   "type": "object"
  },
  "name": "loopskill_pick_best_from_bundle"
 },
 {
  "description": "Propose a new federation registry source (a GitHub repo or catalog of skills) for LoopSkill to federate. Pre-flights the repo (exists? SKILL.md count? license?) BEFORE opening a labelled GitHub issue with the evidence attached — a repo that does not exist or has zero SKILL.md files is reported back instead of filing a junk issue. Rate limited to 1 proposal per 24h per (identity, repo). Accepting a proposal is a config edit (config/federation_sources.yaml), never a code change.",
  "inputSchema": {
   "properties": {
    "agent_id": {
     "type": "string"
    },
    "confirmation": {
     "type": "string"
    },
    "contact": {
     "description": "Optional contact for follow-up.",
     "type": "string"
    },
    "force": {
     "default": false,
     "type": "boolean"
    },
    "repo_url": {
     "description": "https://github.com/<owner>/<repo> URL of the proposed registry.",
     "type": "string"
    },
    "source_id": {
     "description": "Optional proposed source id (slug). Defaults to the repo name.",
     "type": "string"
    },
    "why": {
     "description": "Optional rationale for the proposal.",
     "type": "string"
    }
   },
   "required": [
    "repo_url"
   ],
   "type": "object"
  },
  "name": "loopskill_propose_registry"
 },
 {
  "description": "Submit a working patch (draft PR) to a LoopSkill catalog skill on wisechef-ai/loopskill-api. Use when you have ALREADY fixed a skill locally during install or use and want to ship the fix back so other agents do not hit the same bug. Allowed file paths: SKILL.md, references/*.md, templates/*.{yml,yaml,sh,env,md}. Script changes (scripts/*, install.sh, recipe.yaml) are NOT allowed here — describe those as a comment on the skill-error issue body instead. Hard limits: 3 files max, 200 lines per file, 600 lines total. Rate limited to 1 patch per 24h per (agent, skill). Returns dedup_hash and (eventually) pr_url.",
  "inputSchema": {
   "properties": {
    "agent_id_anon": {
     "type": "string"
    },
    "base_version": {
     "type": "string"
    },
    "evidence_install_id": {
     "type": "string"
    },
    "files": {
     "items": {
      "properties": {
       "content": {
        "type": "string"
       },
       "path": {
        "type": "string"
       }
      },
      "required": [
       "path",
       "content"
      ],
      "type": "object"
     },
     "type": "array"
    },
    "rationale": {
     "type": "string"
    },
    "slug": {
     "type": "string"
    }
   },
   "required": [
    "slug",
    "base_version",
    "files",
    "rationale"
   ],
   "type": "object"
  },
  "name": "loopskill_propose_skill_patch"
 },
 {
  "description": "Publish a bundle you own — flips it from private to public and mints its shareable bundle:// slug. Closes the loop loopskill_compose_bundle_from_links tells you to close: compose, then publish, in MCP only (no REST client needed). Idempotent — publishing an already-public bundle returns success with its current state, not an error. Publishing never counts against your private-bundle tier cap (public bundles are unlimited on every tier).",
  "inputSchema": {
   "properties": {
    "bundle_id": {
     "description": "UUID of the bundle to publish (must be owned by the caller).",
     "type": "string"
    }
   },
   "required": [
    "bundle_id"
   ],
   "type": "object"
  },
  "name": "loopskill_publish_bundle"
 },
 {
  "description": "Publish a composite loop — a deployable autonomous work unit (automation + skills + sub-agents + connectors + verifier gate + state seed). Validates the full manifest server-side.",
  "inputSchema": {
   "properties": {
    "budget_usd": {
     "type": "number"
    },
    "connectors": {
     "items": {
      "type": "object"
     },
     "type": "array"
    },
    "description": {
     "type": "string"
    },
    "is_public": {
     "default": true,
     "type": "boolean"
    },
    "prompt": {
     "type": "string"
    },
    "schedule": {
     "description": "cron expr or '30m' shorthand",
     "type": "string"
    },
    "skills": {
     "items": {
      "type": "object"
     },
     "type": "array"
    },
    "slug": {
     "type": "string"
    },
    "state_seed": {
     "type": "object"
    },
    "subagents_config": {
     "type": "object"
    },
    "tier": {
     "type": "string"
    },
    "title": {
     "type": "string"
    },
    "verifier_slug": {
     "type": "string"
    }
   },
   "required": [
    "slug",
    "title",
    "schedule",
    "verifier_slug",
    "prompt"
   ],
   "type": "object"
  },
  "name": "loopskill_publish_composite_loop"
 },
 {
  "description": "Submit a skill (SKILL.md + optional scripts/references) for review and potential public-catalog inclusion. Runs quality gates locally before opening a labelled GitHub issue. High-severity findings block submission. Rate limited to 1 request per 24h per (identity, slug).",
  "inputSchema": {
   "properties": {
    "changelog": {
     "type": "string"
    },
    "confirmation": {
     "type": "string"
    },
    "content": {
     "description": "SKILL.md content as a string",
     "type": "string"
    },
    "description": {
     "type": "string"
    },
    "force": {
     "default": false,
     "type": "boolean"
    },
    "is_public": {
     "default": true,
     "type": "boolean"
    },
    "license": {
     "default": "MIT",
     "type": "string"
    },
    "references": {
     "items": {
      "properties": {
       "content": {
        "type": "string"
       },
       "path": {
        "type": "string"
       }
      },
      "required": [
       "path",
       "content"
      ],
      "type": "object"
     },
     "type": "array"
    },
    "scripts": {
     "items": {
      "properties": {
       "content": {
        "type": "string"
       },
       "path": {
        "type": "string"
       }
      },
      "required": [
       "path",
       "content"
      ],
      "type": "object"
     },
     "type": "array"
    },
    "slug": {
     "type": "string"
    },
    "tier": {
     "default": "pro",
     "enum": [
      "free",
      "pro",
      "pro_plus",
      "cook",
      "operator"
     ],
     "type": "string"
    },
    "version": {
     "default": "1.0.0",
     "type": "string"
    }
   },
   "required": [
    "slug",
    "content"
   ],
   "type": "object"
  },
  "name": "loopskill_publish_request"
 },
 {
  "description": "Hybrid (vector + BM25) skill recall ranked for the caller's tier.",
  "inputSchema": {
   "properties": {
    "limit": {
     "default": 10,
     "maximum": 50,
     "minimum": 1,
     "type": "integer"
    },
    "local_context_summary": {
     "type": "string"
    },
    "query": {
     "type": "string"
    },
    "tier_filter": {
     "items": {
      "enum": [
       "free",
       "pro",
       "pro_plus",
       "cook",
       "operator"
      ],
      "type": "string"
     },
     "type": "array"
    }
   },
   "required": [
    "query"
   ],
   "type": "object"
  },
  "name": "loopskill_recall"
 },
 {
  "description": "Report that an installed recipe is broken, has wrong instructions, or fails on this host. Use when the user says 'this skill is broken', 'report this skill', or when an install/run fails. Auto-creates a labelled GitHub issue with the failure signature.",
  "inputSchema": {
   "properties": {
    "agent_id": {
     "type": "string"
    },
    "details": {
     "type": "string"
    },
    "provenance_id": {
     "description": "Install-provenance token; routes issue to curator repo (Ph E).",
     "type": "string"
    },
    "signature": {
     "type": "string"
    },
    "slug": {
     "type": "string"
    },
    "summary": {
     "type": "string"
    }
   },
   "required": [
    "slug",
    "signature",
    "summary"
   ],
   "type": "object"
  },
  "name": "loopskill_report_skill_error"
 },
 {
  "description": "Request a new skill. Use when the user says 'skillify X', 'please add X to loopskill', 'we need a skill for X'. Creates a GitHub wishlist issue.",
  "inputSchema": {
   "properties": {
    "agent_id": {
     "type": "string"
    },
    "suggested_sources": {
     "items": {
      "type": "string"
     },
     "type": "array"
    },
    "target_name": {
     "type": "string"
    },
    "why_useful": {
     "type": "string"
    }
   },
   "required": [
    "target_name",
    "why_useful"
   ],
   "type": "object"
  },
  "name": "loopskill_request_skill"
 },
 {
  "description": "Search the public skill catalog, then append federated results. Curated LoopSkill rows come first; federated rows follow, each with an install_ref you can hand straight to loopskill_install. Federation is BEST-EFFORT from a shared cache, not a live guaranteed fan-out: the 'federated' key reports fresh | stale | cold | degraded. 'cold' means this worker has nothing cached for the query — it is NOT a claim that federation has nothing.",
  "inputSchema": {
   "properties": {
    "category": {
     "type": "string"
    },
    "federated_limit": {
     "default": 10,
     "description": "Cap on appended federated rows (context budget).",
     "maximum": 30,
