     "default": "pro",
     "enum": [
      "free",
      "pro",
      "pro_plus",
      "cook",
      "operator"
     ],
     "type": "string"
    },
    "visibility": {
     "default": "private",
     "enum": [
      "private",
      "public_pending_review"
     ],
     "type": "string"
    }
   },
   "required": [
    "slug",
    "content"
   ],
   "type": "object"
  },
  "name": "loopskill_skillify"
 },
 {
  "description": "Phase C stub — resolve a sub-skill key to a scope.",
  "inputSchema": {
   "type": "object"
  },
  "name": "loopskill_subskill_resolve"
 },
 {
  "description": "Synchronise a bundle's skills to their latest published versions. By default (dry_run=false) this APplies updates immediately. Pass dry_run=true to preview the diff without mutating state.",
  "inputSchema": {
   "properties": {
    "cookbook_id": {
     "description": "UUID of the bundle to synchronise.",
     "type": "string"
    },
    "dry_run": {
     "default": false,
     "description": "If true, return the diff without applying changes. Default is false (apply immediately).",
     "type": "boolean"
    }
   },
   "required": [
    "cookbook_id"
   ],
   "type": "object"
  },
  "name": "loopskill_sync"
 },
 {
  "description": "Fork a public skill to create an editable private copy. Returns fork_id and fork_slug. The fork is ready for versioning via POST /api/forks/{fork_id}/version. Idempotent: if the user already forked this skill, returns the existing fork.",
  "inputSchema": {
   "properties": {
    "name": {
     "description": "Human-readable name for the fork.",
     "type": "string"
    },
    "readme": {
     "description": "Optional README for the fork.",
     "type": "string"
    },
    "source_slug": {
     "description": "Slug of the public skill to fork.",
     "type": "string"
    }
   },
   "required": [
    "source_slug",
    "name"
   ],
   "type": "object"
  },
  "name": "loopskill_tailor"
 },
 {
  "description": "Upload a new version tarball to one of your forks (MCP-native). The tarball is passed base64-encoded (MCP can't carry multipart uploads). Mints a fork version and advances the fork's latest pointer. Step 2 of the tailor loop: tailor -> tailor_version -> bundle_attach -> bundle_install. Pro tier or above.",
  "inputSchema": {
   "properties": {
    "changelog": {
     "description": "Optional changelog note for this version.",
     "type": "string"
    },
    "fork_id": {
     "description": "UUID of the fork to version (from loopskill_tailor).",
     "type": "string"
    },
    "semver": {
     "description": "Semantic version, e.g. '1.0.0'.",
     "type": "string"
    },
    "tarball_base64": {
     "description": "Base64-encoded .tar.gz of the tailored skill (max 10 MB decoded).",
     "type": "string"
    }
   },
   "required": [
    "fork_id",
    "tarball_base64",
    "semver"
   ],
   "type": "object"
  },
  "name": "loopskill_tailor_version"
 }
]

